fn determine_winner(a: i8, b: i8, c: i8, d: i8) -> String {
    // Helper to compute the final score for a participant
    fn score(p: i8, t: i8) -> i32 {
        let p = p as i32;
        let t = t as i32;
        // Option 1: 3 * p / 10
        let opt1 = 3 * p / 10;
        // Option 2: p - p * t / 250
        let opt2 = p - (p * t) / 250;
        opt1.max(opt2)
    }

    let s1 = score(a, b);
    let s2 = score(c, d);

    if s1 > s2 {
        "Misha".to_string()
    } else if s2 > s1 {
        "Vasya".to_string()
    } else {
        "Tie".to_string()
    }
}

